css:
:root {
  --bg-base: #0a0a0a;
  --bg-surface: #111111;
  --bg-card: #1f1f1f;
  --border: #2a2a2a;
  --text: #fafafa;
  --text-muted: #a1a1aa;
  --accent: #0ea5e9;
  --success: #22c55e;
  --danger: #ef4444;
  --warning: #f59e0b;

  /* Uma cor por fonte de receita — a mesma em pílula, gráfico e avatar. */
  --src-empresa: #0ea5e9;
  --src-impressionart: #8b5cf6;
  --src-moto: #f59e0b;
  --src-mos: #22c55e;

  --fonte: 'Manrope', sans-serif;
  --fonte-titulo: 'Sora', sans-serif;
  --fonte-mono: 'JetBrains Mono', monospace;
}

body { background: var(--bg-base); color: var(--text); font-family: var(--fonte); }

/* Número em tabela, card ou badge nunca "dança" ao atualizar. */
.bs-num { font-variant-numeric: tabular-nums; }

/* z-index acima do sheet: o diálogo quase sempre nasce de dentro de um, e
   precisa cobrir o pai. */
.bs-conf-camada { position: fixed; inset: 0; z-index: 60; display: flex; align-items: flex-end; }
.bs-sheet-fundo { position: absolute; inset: 0; background: rgba(0, 0, 0, 0.6); }

.bs-conf {
  position: relative; z-index: 10; width: 100%;
  padding: 12px 20px 32px;
  border-top: 1px solid var(--border); border-radius: 24px 24px 0 0;
  background: var(--bg-surface);
}
.bs-sheet-puxador { width: 36px; height: 4px; margin: 0 auto 16px; border-radius: 999px; background: var(--border); }

@media (min-width: 768px) {
  .bs-conf-camada { align-items: center; justify-content: center; }
  /* 380px contra os 420px do sheet: aqui não há formulário, só uma frase. */
  .bs-conf { width: 380px; padding: 12px 20px 24px; border: 1px solid var(--border); border-radius: 24px; }
  .bs-sheet-puxador { display: none; }
}

.bs-conf-titulo { margin-bottom: 8px; font-family: var(--fonte-titulo); font-size: 18px; font-weight: 600; color: var(--text); }
.bs-conf-desc { margin: 0 0 24px; font-size: 13px; line-height: 1.6; color: var(--text-muted); }

/* Os dois do mesmo tamanho: sair é tão fácil quanto confirmar. */
.bs-conf-acoes { display: flex; gap: 8px; }
.bs-conf-btn {
  flex: 1; padding: 12px; border-radius: 12px;
  font-family: var(--fonte); font-size: 13px; font-weight: 600;
}
.bs-conf-cancelar { border: 1px solid var(--border); background: transparent; color: var(--text-muted); }
.bs-conf-confirmar { border: none; background: var(--accent); color: var(--bg-base); }
/* Texto branco no vermelho: #ef4444 é escuro demais pra receber o #0a0a0a. */
.bs-conf-destrutivo { border: none; background: var(--danger); color: var(--text); }
